class Solution {
    struct BIT {
        int n;
        vector<int> tree;
        BIT(int n) : n(n), tree(n + 2, 0) {}
        void add(int i) {
            for (; i <= n; i += i & -i) tree[i]++;
        }
        int query(int i) {
            int s = 0;
            for (; i > 0; i -= i & -i) s += tree[i];
            return s;
        }
    };
public:
    vector<int> resultArray(vector<int>& nums) {
        vector<int> sorted = nums;
        sort(sorted.begin(), sorted.end());
        sorted.erase(unique(sorted.begin(), sorted.end()), sorted.end());
        int m = sorted.size();
        auto getRank = [&](int v) {
            return lower_bound(sorted.begin(), sorted.end(), v) - sorted.begin() + 1;
        };
        BIT bit1(m), bit2(m);
        vector<int> arr1 = {nums[0]}, arr2 = {nums[1]};
        bit1.add(getRank(nums[0]));
        bit2.add(getRank(nums[1]));
        for (int i = 2; i < nums.size(); ++i) {
            int r = getRank(nums[i]);
            int g1 = arr1.size() - bit1.query(r);
            int g2 = arr2.size() - bit2.query(r);
            if (g1 > g2) {
                arr1.push_back(nums[i]);
                bit1.add(r);
            } else if (g2 > g1) {
                arr2.push_back(nums[i]);
                bit2.add(r);
            } else {
                if (arr1.size() <= arr2.size()) {
                    arr1.push_back(nums[i]);
                    bit1.add(r);
                } else {
                    arr2.push_back(nums[i]);
                    bit2.add(r);
                }
            }
        }
        arr1.insert(arr1.end(), arr2.begin(), arr2.end());
        return arr1;
    }
};

class Solution {
    static class BIT {
        int n;
        int[] tree;
        BIT(int n) {
            this.n = n;
            this.tree = new int[n + 2];
        }
        void add(int i) {
            for (; i <= n; i += i & -i) tree[i]++;
        }
        int query(int i) {
            int s = 0;
            for (; i > 0; i -= i & -i) s += tree[i];
            return s;
        }
    }
    public int[] resultArray(int[] nums) {
        int[] sorted = Arrays.stream(nums).distinct().sorted().toArray();
        int m = sorted.length;
        BIT bit1 = new BIT(m);
        BIT bit2 = new BIT(m);
        List<Integer> arr1 = new ArrayList<>();
        List<Integer> arr2 = new ArrayList<>();
        arr1.add(nums[0]);
        arr2.add(nums[1]);
        bit1.add(Arrays.binarySearch(sorted, nums[0]) + 1);
        bit2.add(Arrays.binarySearch(sorted, nums[1]) + 1);
        for (int i = 2; i < nums.length; i++) {
            int r = Arrays.binarySearch(sorted, nums[i]) + 1;
            int g1 = arr1.size() - bit1.query(r);
            int g2 = arr2.size() - bit2.query(r);
            if (g1 > g2) {
                arr1.add(nums[i]);
                bit1.add(r);
            } else if (g2 > g1) {
                arr2.add(nums[i]);
                bit2.add(r);
            } else {
                if (arr1.size() <= arr2.size()) {
                    arr1.add(nums[i]);
                    bit1.add(r);
                } else {
                    arr2.add(nums[i]);
                    bit2.add(r);
                }
            }
        }
        int[] ans = new int[nums.length];
        int idx = 0;
        for (int x : arr1) ans[idx++] = x;
        for (int x : arr2) ans[idx++] = x;
        return ans;
    }
}

var resultArray = function(nums) {
    const sorted = Array.from(new Set(nums)).sort((a, b) => a - b);
    const m = sorted.length;
    const rankMap = new Map();
    sorted.forEach((v, i) => rankMap.set(v, i + 1));
    const tree1 = new Array(m + 2).fill(0);
    const tree2 = new Array(m + 2).fill(0);
    const add = (tree, i) => {
        for (; i <= m; i += i & -i) tree[i]++;
    };
    const query = (tree, i) => {
        let s = 0;
        for (; i > 0; i -= i & -i) s += tree[i];
        return s;
    };
    const arr1 = [nums[0]];
    const arr2 = [nums[1]];
    add(tree1, rankMap.get(nums[0]));
    add(tree2, rankMap.get(nums[1]));
    for (let i = 2; i < nums.length; ++i) {
        const r = rankMap.get(nums[i]);
        const g1 = arr1.length - query(tree1, r);
        const g2 = arr2.length - query(tree2, r);
        if (g1 > g2) {
            arr1.push(nums[i]);
            add(tree1, r);
        } else if (g2 > g1) {
            arr2.push(nums[i]);
            add(tree2, r);
        } else {
            if (arr1.length <= arr2.length) {
                arr1.push(nums[i]);
                add(tree1, r);
            } else {
                arr2.push(nums[i]);
                add(tree2, r);
            }
        }
    }
    return arr1.concat(arr2);
};
